begin;
select plan(24);
insert into auth.users(id,email) values
 ('44444444-4444-4444-8444-444444444444','images@example.test'),
 ('55555555-5555-4555-8555-555555555555','other-images@example.test');
select public.get_or_create_account_profile('44444444-4444-4444-8444-444444444444','images@example.test',true);
select public.get_or_create_account_profile('55555555-5555-4555-8555-555555555555','other-images@example.test',true);
select public.submit_fetch_items('44444444-4444-4444-8444-444444444444',array['https://x.com/user/status/100']);
create temporary table image_job as select * from public.claim_processing_job('44444444-4444-4444-8444-444444444444');
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'X attempt admission is required');
select ok((select admitted from image_job j cross join lateral public.begin_x_fetch(j.user_id,j.id,j.lease_token)),'X fetch admitted');
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading('55555555-5555-4555-8555-555555555555',j.id,j.lease_token,0.16896)),0,'admin cannot reserve another owners image call');
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,gen_random_uuid(),0.16896)),0,'stale lease cannot reserve');
select throws_ok($$select public.reserve_image_reading('44444444-4444-4444-8444-444444444444',gen_random_uuid(),gen_random_uuid(),0)$$,'22023',null,'invalid reservation amount rejected');
update public.items set expires_at=now()-interval '1 second' where id=(select item_id from image_job);
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'expired content cannot reserve image reading');
update public.items set expires_at=now()+interval '1 day' where id=(select item_id from image_job);
update public.account_profiles set status='rejected' where user_id='44444444-4444-4444-8444-444444444444';
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'rejected account cannot reserve image reading');
update public.account_profiles set status='approved' where user_id='44444444-4444-4444-8444-444444444444';
select public.set_user_budget('44444444-4444-4444-8444-444444444444',0.01);
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'budget blocks inference before payment');
select is((select processing_stage from public.items where id=(select item_id from image_job)),'image_budget_exhausted','budget rejection explains image reading');
update public.jobs q set status='processing',lease_token=j.lease_token,lease_expires_at=now()+interval '60 seconds' from image_job j where q.id=j.id;
update public.items set status='processing' where id=(select item_id from image_job);
select public.set_user_budget('44444444-4444-4444-8444-444444444444',10);
create temporary table image_reservation as select r.id from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896) r;
select is((select count(*)::int from image_reservation),1,'one image batch reserved');
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'same image slot is never returned twice');
select is((select reserved_usd from public.get_usage_summary('44444444-4444-4444-8444-444444444444')),0.16896::numeric,'image hold shares monthly capacity');
select is((select purpose from public.usage_reservations where id=(select id from image_reservation)),'image_extraction','image charge distinct from assessment');
update public.jobs set lease_expires_at=now()-interval '1 second' where id=(select id from image_job);
select is((select count(*)::int from image_job j cross join image_reservation r cross join lateral public.record_image_generation(j.user_id,j.id,r.id,'image-generation')),1,'generation survives lost lease');
select is((select count(*)::int from image_job j cross join image_reservation r cross join lateral public.record_image_generation('55555555-5555-4555-8555-555555555555',j.id,r.id,'other')),0,'another owner cannot record image generation');
select is((select count(*)::int from image_job j cross join image_reservation r cross join lateral public.record_image_generation(j.user_id,j.id,r.id,'replacement')),0,'generation cannot be overwritten');
select public.settle_analysis('44444444-4444-4444-8444-444444444444',(select id from image_reservation),0.004);
select is((select spent_usd from public.get_usage_summary('44444444-4444-4444-8444-444444444444')),0.004::numeric,'actual image cost is settled');
update public.jobs q set lease_token=j.lease_token,lease_expires_at=now()+interval '60 seconds' from image_job j where q.id=j.id;
select is((select count(*)::int from image_job j cross join lateral public.reserve_image_reading(j.user_id,j.id,j.lease_token,0.16896)),0,'settled slot is not silently repeated');
update public.jobs set status='awaiting_manual_content',processing_stage='image_reading_failed' where id=(select id from image_job);
update public.items set status='awaiting_manual_content',processing_stage='image_reading_failed',failure_reason='image_reading_failed' where id=(select item_id from image_job);
select public.resume_processing_item('44444444-4444-4444-8444-444444444444',(select item_id from image_job));
select ok((select image_reservation_id is null and not x_fetch_started from public.jobs where id=(select id from image_job)),'explicit terminal fetch retry resets both admissions');
update public.jobs set status='awaiting_manual_content',processing_stage='image_reading_uncertain' where id=(select id from image_job);
update public.items set status='awaiting_manual_content',processing_stage='image_reading_uncertain',failure_reason='image_reading_uncertain' where id=(select item_id from image_job);
select is((select count(*)::int from image_job j cross join lateral public.resume_processing_item(j.user_id,j.item_id)),0,'uncertain image reading cannot retry');
insert into public.usage_reservations(id,user_id,job_id,month,amount_usd,purpose)
 select '66666666-6666-4666-8666-666666666666',user_id,id,date_trunc('month',now())::date,0.16896,'image_extraction' from image_job;
select public.delete_items('44444444-4444-4444-8444-444444444444',array[(select item_id from image_job)],true);
select ok((select job_id is null and state='reserved' from public.usage_reservations where id='66666666-6666-4666-8666-666666666666'),'deletion preserves unknown image costs');
select is((select count(*)::int from image_job j cross join lateral public.record_image_generation(j.user_id,j.id,'66666666-6666-4666-8666-666666666666','late-image')),1,'late image generation survives content deletion');
set local role authenticated;
select throws_ok($$select public.reserve_image_reading('44444444-4444-4444-8444-444444444444',gen_random_uuid(),gen_random_uuid(),0.16896)$$,'42501',null,'image admission is server-only');
select throws_ok($$select public.record_image_generation('44444444-4444-4444-8444-444444444444',gen_random_uuid(),gen_random_uuid(),'gen')$$,'42501',null,'image generation recording is server-only');
reset role;
select * from finish();
rollback;
